// NEC 2023 Compliance Checker
// Comprehensive electrical code compliance validation

const projectData = $input.first().json;

// Extract project details
const {
  projectId,
  projectType = 'residential',
  squareFootage,
  roomLayout = [],
  electricalElements = [],
  panelSpecifications = {},
  proposedCircuits = [],
  specialSystems = []
} = projectData;

// NEC 2023 Compliance Rules Database
const NECRules = {
  // Article 210 - Branch Circuits
  branchCircuits: {
    '210.8': {
      title: 'GFCI Protection',
      residential: {
        required: ['bathroom', 'kitchen', 'laundry', 'garage', 'basement', 'outdoor'],
        exceptions: ['kitchen disposal', 'kitchen dishwasher']
      },
      commercial: {
        required: ['bathroom', 'kitchen', 'rooftop', 'outdoor', 'wet_locations']
      }
    },
    '210.11': {
      title: 'Branch Circuit Requirements',
      residential: {
        lighting: { min_circuits: 1, load_per_sqft: 3 },
        small_appliance: { min_circuits: 2, load_per_circuit: 1500 },
        laundry: { min_circuits: 1, load_per_circuit: 1500 }
      }
    },
    '210.12': {
      title: 'AFCI Protection',
      residential: {
        required: ['family_room', 'dining_room', 'living_room', 'parlor', 'library', 'den', 'bedroom', 'sunroom', 'recreation_room', 'closet', 'hallway', 'laundry'],
        exceptions: ['bathroom', 'garage', 'unfinished_basement']
      }
    },
    '210.52': {
      title: 'Dwelling Unit Receptacle Outlets',
      spacing: {
        wall_outlets: { max_distance: 6, units: 'feet' },
        kitchen_countertop: { max_distance: 4, units: 'feet' },
        island_countertop: { min_outlets: 1, min_length: 24, units: 'inches' }
      }
    }
  },
  // Article 220 - Load Calculations
  loadCalculations: {
    '220.12': {
      title: 'General Lighting Load',
      residential: { load_per_sqft: 3, units: 'VA' },
      commercial: { load_per_sqft: 1, units: 'VA' }
    },
    '220.52': {
      title: 'Small Appliance and Laundry Loads',
      small_appliance: { min_circuits: 2, load_per_circuit: 1500 },
      laundry: { circuits: 1, load: 1500 }
    }
  },
  // Article 314 - Outlet Boxes
  outletBoxes: {
    '314.16': {
      title: 'Number of Conductors in Outlet Boxes',
      fill_calculation: {
        '14_awg': 2.0, // cubic inches per conductor
        '12_awg': 2.25,
        '10_awg': 2.5
      }
    }
  }
};

// Compliance checking functions
function checkGFCICompliance(rooms, elements) {
  const violations = [];
  const warnings = [];

  const gfciRequired = NECRules.branchCircuits['210.8'][projectType]?.required || [];

  rooms.forEach(room => {
    const roomType = room.type?.toLowerCase();
    const requiresGFCI = gfciRequired.some(req => roomType.includes(req));

    if (requiresGFCI) {
      const roomElements = elements.filter(el => el.room?.toLowerCase() === room.name?.toLowerCase());
      const hasGFCI = roomElements.some(el => el.type === 'outlet' && el.specifications?.type === 'GFCI');

      if (!hasGFCI) {
        violations.push({
          code: 'NEC 210.8',
          severity: 'critical',
          description: `GFCI protection required in ${room.name} (${roomType})`,
          location: room.name,
          solution: 'Install GFCI outlets or GFCI circuit breaker'
        });
      }
    }
  });

  return { violations, warnings };
}

function checkAFCICompliance(rooms, circuits) {
  const violations = [];
  const warnings = [];

  if (projectType !== 'residential') {
    return { violations, warnings };
  }

  const afciRequired = NECRules.branchCircuits['210.12'].residential.required;
  const afciExceptions = NECRules.branchCircuits['210.12'].residential.exceptions;

  rooms.forEach(room => {
    const roomType = room.type?.toLowerCase();
    const requiresAFCI = afciRequired.some(req => roomType.includes(req.replace('_', ' ')));
    const isException = afciExceptions.some(exc => roomType.includes(exc.replace('_', ' ')));

    if (requiresAFCI && !isException) {
      const roomCircuits = circuits.filter(c => c.serves_rooms?.includes(room.name));
      const hasAFCI = roomCircuits.some(c => c.protection?.includes('AFCI'));

      if (!hasAFCI) {
        violations.push({
          code: 'NEC 210.12',
          severity: 'critical',
          description: `AFCI protection required for ${room.name} (${roomType})`,
          location: room.name,
          solution: 'Install AFCI circuit breaker or combination AFCI/GFCI'
        });
      }
    }
  });

  return { violations, warnings };
}

function checkOutletSpacing(rooms, elements) {
  const violations = [];
  const warnings = [];

  const spacingRules = NECRules.branchCircuits['210.52'].spacing;

  rooms.forEach(room => {
    const roomOutlets = elements.filter(el => 
      el.room?.toLowerCase() === room.name?.toLowerCase() && el.type === 'outlet'
    );

    if (roomOutlets.length === 0 && room.type !== 'bathroom') {
      violations.push({
        code: 'NEC 210.52',
        severity: 'major',
        description: `No outlets found in ${room.name}`,
        location: room.name,
        solution: 'Install outlets per NEC spacing requirements'
      });
      return;
    }

    // Check wall outlet spacing (simplified - would need actual wall measurements)
    if (room.type?.toLowerCase() === 'kitchen') {
      const counterOutlets = roomOutlets.filter(o => o.location?.includes('counter'));
      if (counterOutlets.length < 2) {
        warnings.push({
          code: 'NEC 210.52',
          severity: 'minor',
          description: `Kitchen may need more countertop outlets in ${room.name}`,
          location: room.name,
          solution: 'Verify 4-foot spacing rule for countertop outlets'
        });
      }
    }
  });

  return { violations, warnings };
}

function checkLoadCalculations(squareFootage, circuits, appliances = []) {
  const violations = [];
  const warnings = [];

  // General lighting load calculation
  const requiredLightingLoad = squareFootage * NECRules.loadCalculations['220.12'][projectType].load_per_sqft;
  const lightingCircuits = circuits.filter(c => c.type === 'lighting');
  const totalLightingCapacity = lightingCircuits.reduce((sum, c) => sum + (c.amperage * c.voltage * 0.8), 0);

  if (totalLightingCapacity < requiredLightingLoad) {
    violations.push({
      code: 'NEC 220.12',
      severity: 'major',
      description: `Insufficient lighting load capacity: ${totalLightingCapacity}VA provided, ${requiredLightingLoad}VA required`,
      location: 'General',
      solution: 'Add additional lighting circuits or increase circuit capacity'
    });
  }

  // Small appliance circuits
  if (projectType === 'residential') {
    const smallApplianceCircuits = circuits.filter(c => c.type === 'small_appliance');
    const minRequired = NECRules.loadCalculations['220.52'].small_appliance.min_circuits;

    if (smallApplianceCircuits.length < minRequired) {
      violations.push({
        code: 'NEC 220.52',
        severity: 'critical',
        description: `Insufficient small appliance circuits: ${smallApplianceCircuits.length} provided, ${minRequired} required`,
        location: 'Kitchen',
        solution: 'Add dedicated 20A small appliance circuits'
      });
    }
  }

  return { violations, warnings };
}

function checkPanelRequirements(panelSpecs, totalLoad) {
  const violations = [];
  const warnings = [];

  const panelCapacity = panelSpecs.amperage || 100;
  const panelVoltage = panelSpecs.voltage || 120;
  const maxCapacity = panelCapacity * panelVoltage * 0.8; // 80% rule

  if (totalLoad > maxCapacity) {
    violations.push({
      code: 'NEC 220.40',
      severity: 'critical',
      description: `Panel capacity exceeded: ${totalLoad}VA load, ${maxCapacity}VA capacity`,
      location: 'Main Panel',
      solution: 'Upgrade to larger panel or reduce connected load'
    });
  } else if (totalLoad > maxCapacity * 0.9) {
    warnings.push({
      code: 'NEC 220.40',
      severity: 'minor',
      description: `Panel capacity approaching limit: ${totalLoad}VA load, ${maxCapacity}VA capacity`,
      location: 'Main Panel',
      solution: 'Consider future expansion needs'
    });
  }

  return { violations, warnings };
}

// Perform comprehensive compliance check
const complianceResults = {
  projectId,
  timestamp: new Date().toISOString(),
  necVersion: '2023',
  projectType,
  checks: {
    gfci: checkGFCICompliance(roomLayout, electricalElements),
    afci: checkAFCICompliance(roomLayout, proposedCircuits),
    outlets: checkOutletSpacing(roomLayout, electricalElements),
    loads: checkLoadCalculations(squareFootage, proposedCircuits),
    panel: checkPanelRequirements(panelSpecifications, proposedCircuits.reduce((sum, c) => sum + (c.load || 0), 0))
  }
};

// Aggregate all violations and warnings
const allViolations = [];
const allWarnings = [];

Object.values(complianceResults.checks).forEach(check => {
  allViolations.push(...check.violations);
  allWarnings.push(...check.warnings);
});

// Calculate compliance score
const totalIssues = allViolations.length + allWarnings.length;
const criticalViolations = allViolations.filter(v => v.severity === 'critical').length;
const majorViolations = allViolations.filter(v => v.severity === 'major').length;
const minorWarnings = allWarnings.filter(w => w.severity === 'minor').length;

// Scoring: Critical = -20, Major = -10, Minor = -2
const scoreDeduction = (criticalViolations * 20) + (majorViolations * 10) + (minorWarnings * 2);
const complianceScore = Math.max(0, 100 - scoreDeduction);

// Generate compliance status
let complianceStatus = 'COMPLIANT';
if (criticalViolations > 0) {
  complianceStatus = 'NON_COMPLIANT';
} else if (majorViolations > 0) {
  complianceStatus = 'REQUIRES_ATTENTION';
} else if (minorWarnings > 0) {
  complianceStatus = 'COMPLIANT_WITH_WARNINGS';
}

// Create detailed report
const report = {
  ...complianceResults,
  summary: {
    status: complianceStatus,
    score: complianceScore,
    totalIssues,
    breakdown: {
      critical: criticalViolations,
      major: majorViolations,
      minor: minorWarnings
    }
  },
  violations: allViolations,
  warnings: allWarnings,
  recommendations: [
    ...allViolations.map(v => ({
      priority: 'high',
      code: v.code,
      action: v.solution,
      location: v.location
    })),
    ...allWarnings.map(w => ({
      priority: 'medium',
      code: w.code,
      action: w.solution,
      location: w.location
    }))
  ],
  nextSteps: complianceStatus === 'COMPLIANT' ? [
    'Review with electrical engineer',
    'Submit for permit approval',
    'Schedule inspection phases'
  ] : [
    'Address critical violations immediately',
    'Review design with NEC expert',
    'Revise electrical plans',
    'Resubmit for compliance check'
  ]
};

return [{ json: report }];

// Generate Compliance Certificate or Violation Report
const complianceData = $('NEC Compliance Engine').first().json;
const advancedValidation = $('Advanced NEC Validation').first();

// Merge advanced validation results if available
let enhancedReport = { ...complianceData };

if (advancedValidation && advancedValidation.json && !advancedValidation.json.error) {
  const advancedResults = advancedValidation.json;

  // Add advanced validation insights
  enhancedReport.advancedValidation = {
    aiRecommendations: advancedResults.aiRecommendations || [],
    riskAssessment: advancedResults.riskAssessment || 'medium',
    costImpact: advancedResults.costImpact || null,
    timelineImpact: advancedResults.timelineImpact || null
  };

  // Update compliance score with advanced factors
  if (advancedResults.adjustedScore) {
    enhancedReport.summary.score = advancedResults.adjustedScore;
  }
}

// Generate compliance certificate for compliant projects
if (enhancedReport.summary.status === 'COMPLIANT') {
  enhancedReport.certificate = {
    certificateId: `NEC-CERT-${enhancedReport.projectId}-${Date.now()}`,
    issuedDate: new Date().toISOString(),
    validUntil: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString(), // 1 year
    certifyingAuthority: 'ElectricalAI Pro NEC Compliance Engine',
    necVersion: '2023',
    certificationLevel: enhancedReport.summary.score >= 95 ? 'Gold' : enhancedReport.summary.score >= 85 ? 'Silver' : 'Bronze',
    digitalSignature: `${enhancedReport.projectId}-${Date.now()}-verified`,
    qrCode: `https://electricalai.pro/verify/${enhancedReport.projectId}`
  };
}

// Generate detailed violation report for non-compliant projects
if (enhancedReport.summary.status === 'NON_COMPLIANT') {
  enhancedReport.violationReport = {
    reportId: `NEC-VIOL-${enhancedReport.projectId}-${Date.now()}`,
    severity: 'CRITICAL',
    mustFixItems: enhancedReport.violations.filter(v => v.severity === 'critical'),
    estimatedFixCost: enhancedReport.violations.reduce((sum, v) => {
      const costMap = { critical: 1500, major: 800, minor: 200 };
      return sum + (costMap[v.severity] || 0);
    }, 0),
    estimatedFixTime: enhancedReport.violations.length * 2, // 2 hours per violation
    reinspectionRequired: true
  };
}

// Create inspector-ready summary
enhancedReport.inspectorSummary = {
  projectCompliant: enhancedReport.summary.status === 'COMPLIANT',
  criticalIssues: enhancedReport.violations.filter(v => v.severity === 'critical').length,
  majorIssues: enhancedReport.violations.filter(v => v.severity === 'major').length,
  minorIssues: enhancedReport.warnings.filter(w => w.severity === 'minor').length,
  overallScore: enhancedReport.summary.score,
  recommendedAction: enhancedReport.summary.status === 'COMPLIANT' ? 'APPROVE' : 'REVISE_AND_RESUBMIT',
  inspectionPhases: {
    roughIn: enhancedReport.summary.status === 'COMPLIANT' ? 'READY' : 'NOT_READY',
    trim: 'PENDING',
    final: 'PENDING'
  }
};

// Add compliance tracking metadata
enhancedReport.metadata = {
  generatedBy: 'ElectricalAI Pro NEC 2023 Compliance Engine',
  version: '2.1.0',
  processingTime: Date.now() - new Date(enhancedReport.timestamp).getTime(),
  rulesChecked: Object.keys(enhancedReport.checks).length,
  confidenceLevel: enhancedReport.advancedValidation ? 'high' : 'medium'
};

return [{ json: enhancedReport }];

// Format compliance response for frontend
const complianceReport = $('Save Compliance Report').first().json;

const response = {
  success: true,
  projectId: complianceReport.projectId,
  compliance: {
    status: complianceReport.summary.status,
    score: complianceReport.summary.score,
    certificateId: complianceReport.certificate?.certificateId,
    validUntil: complianceReport.certificate?.validUntil
  },
  issues: {
    critical: complianceReport.summary.breakdown.critical,
    major: complianceReport.summary.breakdown.major,
    minor: complianceReport.summary.breakdown.minor,
    total: complianceReport.summary.totalIssues
  },
  violations: complianceReport.violations.map(v => ({
    code: v.code,
    severity: v.severity,
    description: v.description,
    location: v.location,
    solution: v.solution
  })),
  recommendations: complianceReport.recommendations.slice(0, 5), // Top 5 recommendations
  inspector: {
    ready: complianceReport.inspectorSummary.projectCompliant,
    action: complianceReport.inspectorSummary.recommendedAction,
    phases: complianceReport.inspectorSummary.inspectionPhases
  },
  nextSteps: complianceReport.nextSteps,
  certificate: complianceReport.certificate || null,
  processingTime: complianceReport.metadata.processingTime,
  timestamp: complianceReport.timestamp
};

return [{ json: response }];
